const sampleItemsJson = r'''[{"uid": 1, "cat_uid": 219, "category_name": "Cuộc sống UEH", "title": "[Photo Story | UEH Alumni Gratitude Campus Tour 2026] Cựu sinh viên Khoa KQM trở về UEH\r\n", "short_desc": "Sáng ngày 23/9/2026, các thế hệ Cựu sinh viên Khoa KQM đã cùng trở về UEH trong hành trình UEH Alumni Gratitude Campus Tour 2026 - “Về nơi mình thuộc về - Where We Belong”.\r\n", "post_date": "2026-10-13T08:54:00", "sdgs": [4, 8, 17], "is_featured": true, "background_img": "https://api.ngoisaoviet.info/images/upload/img_background/ueh-background-639274789085988285.png", "thumbnail_img": "https://api.ngoisaoviet.info/images/upload/thumbnail/ueh-thumbnail-639274789085966665.png"}, {"uid": 304, "cat_uid": 222, "category_name": "Tuyển sinh & Hướng nghiệp", "title": "Khám phá lộ trình học tập linh hoạt chỉ có ở chương trình Thạc sĩ Quản trị Đô thị Thông minh và Sáng tạo tại UEH-ISCM", "short_desc": "Trong bối cảnh đô thị hóa diễn ra mạnh mẽ và Cách mạng Công nghiệp 4.0 đang làm thay đổi phương thức sống, làm việc và quản lý đô thị, nhu cầu về nguồn nhân lực chất lượng cao trong lĩnh vực quản trị đô thị thông minh ngày càng trở nên cấp thiết. Đón đầu xu hướng đó, từ năm 2021, Đại học Kinh tế TP. Hồ Chí Minh (UEH) đã tiên phong triển khai Chương trình Thạc sĩ Quản trị Đô thị Thông minh và Sáng tạo (Master of Smart City and Innovation Management – MSCIM), do Viện Đô thị Thông minh và Quản lý (ISCM) quản lý.", "post_date": "2026-04-01T07:00:00", "sdgs": [4, 11], "is_featured": false, "background_img": "https://api.ngoisaoviet.infohttps://iscm-api.ueh.edu.vn/public/static/images/open-admission/kham-pha-lo-trinh-hoc-tap-linh-hoat-chi-co-o-chuong-trinh-thac-si-quan-tri-do-thi-thong-minh-va-sang-tao-tai-ueh-iscm/image1.png", "thumbnail_img": "https://api.ngoisaoviet.infohttps://iscm-api.ueh.edu.vn/public/static/images/open-admission/kham-pha-lo-trinh-hoc-tap-linh-hoat-chi-co-o-chuong-trinh-thac-si-quan-tri-do-thi-thong-minh-va-sang-tao-tai-ueh-iscm/image1.png"}, {"uid": 201, "cat_uid": 221, "category_name": "Báo chí nói về UEH", "title": "Gần 1.000 chuyên gia đồng hành cùng UEH kết nối đào tạo và thực tiễn", "short_desc": "Bài viết của Báo Thanh Niên ngày 6/10/2026 về hoạt động kết nối chuyên gia thực tiễn đồng hành cùng UEH trong đào tạo.\r\n\r\n\r\n\r\n", "post_date": "2026-10-12T16:21:00", "sdgs": [4, 8, 17], "is_featured": false, "background_img": null, "thumbnail_img": "https://api.ngoisaoviet.info/images/upload/thumbnail/ueh-thumbnail-639274195773917012.png"}, {"uid": 154, "cat_uid": 220, "category_name": "Khoa học - Góc nhìn chuyên gia", "title": "Không chỉ xây dựng hệ thống cơ sở hạ tầng giao thông hiện đại, Việt Nam đang cần một thế hệ mới để vận hành tương lai giao thông thông minh", "short_desc": "<span style=\"font-family: &quot;Times New Roman&quot;, serif;\"><em>\"Cuộc cạnh tranh của các quốc gia trong tương lai sẽ không nằm ở việc ai xây được nhiều hạ tầng hơn, mà ở việc ai có đủ nguồn nhân lực để vận hành những hệ thống đó hiệu quả hơn.\"</em></span>", "post_date": "2026-07-14T14:17:23", "sdgs": [4, 9, 11], "is_featured": false, "background_img": null, "thumbnail_img": null}, {"uid": 18, "cat_uid": 219, "category_name": "Cuộc sống UEH", "title": "Vở kịch “Nữ sĩ Hồ Xuân Hương – Sống lại cuộc đời và thi ca của “Bà Chúa Thơ Nôm” qua góc nhìn sân khấu đầy cảm xúc tại UEH", "short_desc": "Ngày 30/09/2026, tại Hội trường B1.301, UEH Nguyễn Tri Phương, vở kịch nói Nữ sĩ Hồ Xuân Hương của tác giả Nguyễn Đức Minh, dưới sự dàn dựng của NSND Thúy Mùi, đã thu hút gần 300 khán giả. Trong hơn 120 phút, tác phẩm đưa người xem đến với thế giới thơ ca của “Bà Chúa Thơ Nôm”, đồng thời tái hiện trên sân khấu cuộc đời và số phận của nữ sĩ tài hoa qua ngôn ngữ kịch giàu sức biểu đạt. Từ những vần thơ quen thuộc, tác phẩm mở ra một góc nhìn sinh động về Hồ Xuân Hương, người phụ nữ tài năng, cá tính và bản lĩnh nhưng cũng trải qua nhiều thăng trầm, truân chuyên trong cuộc đời.", "post_date": "2026-10-06T11:11:00", "sdgs": [4, 3, 11], "is_featured": false, "background_img": "https://api.ngoisaoviet.info/images/upload/img_background/ueh-background-639270637581861942.png", "thumbnail_img": "https://api.ngoisaoviet.info/images/upload/thumbnail/ueh-thumbnail-639270637581846745.png"}, {"uid": 6, "cat_uid": 219, "category_name": "Cuộc sống UEH", "title": "Acoustic Show: After Hours – Thành phố mang âm hưởng của màn đêm sâu thẳm", "short_desc": "", "post_date": "2026-10-09T14:42:55", "sdgs": [4], "is_featured": false, "background_img": null, "thumbnail_img": "https://api.ngoisaoviet.infohttps://dsa.ueh.edu.vn/wp-content/uploads/2026/10/BAO_0699.webp"}]''';

/// GET /api/news/304: có content HTML, ảnh bị ghép domain.
const detail304Json = r'''{"content": "<p><img src=\"https://iscm-api.ueh.edu.vn/public/static/images/open-admission/kham-pha-lo-trinh-hoc-tap-linh-hoat-chi-co-o-chuong-trinh-thac-si-quan-tri-do-thi-thong-minh-va-sang-tao-tai-ueh-iscm/image1.png\" style=\"width:100%\" /></p>\r\n\r\n<p><span>Chương tr&igrave;nh được thiết kế theo hướng li&ecirc;n ng&agrave;nh, kết hợp kiến thức về quản trị, c&ocirc;ng nghệ, quy hoạch v&agrave; ph&aacute;t triển bền vững. Điểm nổi bật của MSCIM l&agrave; lộ tr&igrave;nh học tập linh hoạt, cho ph&eacute;p học vi&ecirc;n lựa chọn hướng học ph&ugrave; hợp với mục ti&ecirc;u nghề nghiệp, định hướng nghi&ecirc;n cứu v&agrave; điều kiện c&aacute; nh&acirc;n. Theo th&ocirc;ng tin tuyển sinh cập nhật năm 2025 từ UEH, chương tr&igrave;nh hiện c&oacute;<em> &ldquo;ba lựa chọn về lộ tr&igrave;nh&rdquo;</em>, gi&uacute;p người học vừa tiếp cận kiến thức chuy&ecirc;n s&acirc;u, vừa mở rộng g&oacute;c nh&igrave;n quốc tế v&agrave; tăng cường trải nghiệm thực tiễn.</span></p>\r\n\r\n<p><span><strong>Lộ tr&igrave;nh 1: Học tập to&agrave;n thời gian tại UEH - 2 năm </strong></span></p>\r\n\r\n<p><span>Đ&acirc;y l&agrave; lộ tr&igrave;nh phổ biến d&agrave;nh cho những người học mong muốn ho&agrave;n th&agrave;nh to&agrave;n bộ chương tr&igrave;nh tại Việt Nam trong thời gian 2 năm. Lộ tr&igrave;nh n&agrave;y ph&ugrave; hợp với c&aacute;c học vi&ecirc;n muốn tập trung x&acirc;y dựng nền tảng kiến thức chuy&ecirc;n m&ocirc;n trong m&ocirc;i trường học thuật của UEH, đồng thời thuận lợi trong việc c&acirc;n bằng giữa học tập v&agrave; c&ocirc;ng việc.</span></p>\r\n\r\n<p><span>Trong qu&aacute; tr&igrave;nh học tại Viện Đ&ocirc; thị Th&ocirc;ng minh v&agrave; Quản l&yacute; (ISCM), học vi&ecirc;n sẽ được trang bị kiến thức li&ecirc;n ng&agrave;nh về quản trị đ&ocirc; thị, đổi mới s&aacute;ng tạo, c&ocirc;ng nghệ v&agrave; ph&aacute;t triển bền vững. Chương tr&igrave;nh ch&uacute; trọng ph&aacute;t triển tư duy ph&acirc;n t&iacute;ch, khả năng giải quyết vấn đề v&agrave; kỹ năng ứng dụng kiến thức v&agrave;o thực tiễn đ&ocirc; thị. </span></p>\r\n\r\n<p><span>Sau khi ho&agrave;n th&agrave;nh chương tr&igrave;nh, học vi&ecirc;n sẽ nhận bằng<strong> </strong>Thạc sĩ Quản trị Đ&ocirc; thị Th&ocirc;ng minh v&agrave; S&aacute;ng tạo (Master of Smart City and Innovation Management) do UEH cấp.</span></p>\r\n\r\n<p><span><strong>Lộ tr&igrave;nh 2: Cơ hội nhận song bằng khi học tập 18 th&aacute;ng tại UEH v&agrave; 6 th&aacute;ng quốc tế</strong></span></p>\r\n\r\n<h4><span><strong>Trao đổi học tập tại Handong Global University (H&agrave;n Quốc) &ndash; Kết nối c&ocirc;ng nghệ v&agrave; ph&aacute;t triển bền vững</strong></span></h4>\r\n\r\n<p><span>Trong thời gian học tập tại HGU, học vi&ecirc;n sẽ được tiếp cận c&aacute;c nội dung li&ecirc;n quan đến mối quan hệ giữa con người, m&ocirc;i trường v&agrave; hệ thống x&atilde; hội, đặc biệt trong bối cảnh chuyển đổi số v&agrave; C&aacute;ch mạng C&ocirc;ng nghiệp 4.0. Chương tr&igrave;nh gi&uacute;p người học hiểu r&otilde; hơn c&aacute;ch ứng dụng c&ocirc;ng nghệ v&agrave; tư duy li&ecirc;n ng&agrave;nh để giải quyết c&aacute;c vấn đề ph&aacute;t triển đ&ocirc; thị hiện nay.</span></p>\r\n\r\n<p><span>Sau khi tốt nghiệp, học vi&ecirc;n sẽ nhận hai bằng thạc sĩ:</span></p>\r\n\r\n<ul>\r\n\t<li>\r\n\t<p><span>Thạc sĩ Quản trị Đ&ocirc; thị Th&ocirc;ng minh v&agrave; S&aacute;ng tạo (MSCIM) do UEH cấp</span></p>\r\n\t</li>\r\n</ul>\r\n\r\n<ul>\r\n\t<li>\r\n\t<p><span>Thạc sĩ C&ocirc;ng nghệ v&agrave; Sinh th&aacute;i học Con người (Master of Human Ecology and Technology) do Handong Global University cấp</span></p>\r\n\t</li>\r\n</ul>\r\n\r\n<h4><span><strong>Trao đổi học tập tại Hasselt University (Bỉ) &ndash; G&oacute;c nh&igrave;n đa ng&agrave;nh về giao th&ocirc;ng v&agrave; đ&ocirc; thị</strong></span></h4>\r\n\r\n<p><span>UHasselt được biết đến với c&aacute;c chương tr&igrave;nh nghi&ecirc;n cứu mạnh về giao th&ocirc;ng bền vững v&agrave; quy hoạch đ&ocirc; thị. Trong thời gian học tập tại đ&acirc;y, học vi&ecirc;n sẽ được tiếp cận g&oacute;c nh&igrave;n đa ng&agrave;nh về giao th&ocirc;ng, bao gồm c&aacute;c kh&iacute;a cạnh x&atilde; hội, t&acirc;m l&yacute;, m&ocirc;i trường, hạ tầng v&agrave; quy hoạch đ&ocirc; thị. C&aacute;ch tiếp cận n&agrave;y gi&uacute;p người học hiểu r&otilde; hơn vai tr&ograve; của hệ thống giao th&ocirc;ng trong việc th&uacute;c đẩy tăng trưởng kinh tế, cải thiện m&ocirc;i trường sống v&agrave; n&acirc;ng cao chất lượng cuộc sống của người d&acirc;n.</span></p>\r\n\r\n<p><span>Sau khi ho&agrave;n th&agrave;nh chương tr&igrave;nh, học vi&ecirc;n sẽ nhận hai bằng thạc sĩ:</span></p>\r\n\r\n<ul>\r\n\t<li>\r\n\t<p><span>Thạc sĩ Quản trị Đ&ocirc; thị Th&ocirc;ng minh v&agrave; S&aacute;ng tạo (MSCIM) do UEH cấp</span></p>\r\n\t</li>\r\n\t<li>\r\n\t<p><span>Thạc sĩ Khoa học Giao th&ocirc;ng (Master of Transportation Sciences) do Hasselt University cấp</span></p>\r\n\t</li>\r\n</ul>\r\n\r\n<h4><span><strong>Lựa chọn lộ tr&igrave;nh ph&ugrave; hợp để kiến tạo tương lai đ&ocirc; thị bền vững</strong></span></h4>\r\n\r\n<p><span>Chương tr&igrave;nh MSCIM tại UEH được thiết kế như một h&agrave;nh tr&igrave;nh học tập linh hoạt v&agrave; c&aacute; nh&acirc;n h&oacute;a, gi&uacute;p học vi&ecirc;n lựa chọn lộ tr&igrave;nh ph&ugrave; hợp với định hướng ph&aacute;t triển của bản th&acirc;n.</span></p>\r\n\r\n<p><span>D&ugrave; lựa chọn học tập ho&agrave;n to&agrave;n tại UEH để x&acirc;y dựng nền tảng vững chắc, hay tham gia c&aacute;c chương tr&igrave;nh trao đổi quốc tế để mở rộng trải nghiệm học thuật v&agrave; nhận hai bằng thạc sĩ, tất cả c&aacute;c lộ tr&igrave;nh đều hướng đến mục ti&ecirc;u chung: đ&agrave;o tạo nguồn nh&acirc;n lực c&oacute; năng lực quản trị đ&ocirc; thị th&ocirc;ng minh, s&aacute;ng tạo v&agrave; bền vững trong bối cảnh ph&aacute;t triển đ&ocirc; thị hiện đại.</span></p>\r\n\r\n<p><span>Hiện nay, Chương tr&igrave;nh Thạc sĩ Quản trị Đ&ocirc; thị Th&ocirc;ng minh v&agrave; S&aacute;ng tạo (MSCIM) đang mở nhận hồ sơ<strong> </strong>thi tuyển <strong>Đợt 2 năm 2026.</strong></span></p>\r\n\r\n<p><span>Th&ocirc;ng tin chi tiết về điều kiện tuyển sinh: </span><a href=\"https://tuyensinh.ueh.edu.vn/bai-viet/ueh-tuyen-sinh-dao-tao-trinh-do-thac-si-dot-2-nam-2026-voi-da-dang-cac-chuong-trinh-tieng-viet-tieng-anh-toan-phan-va-he-dieu-hanh-cao-cap/\" rel=\"noopener noreferrer nofollow\" target=\"_blank\"><span><u>LINK</u></span></a><span> </span></p>\r\n\r\n<p><span>Th&ocirc;ng tin về cấu tr&uacute;c chương tr&igrave;nh v&agrave; chuẩn đầu ra: </span><a href=\"https://tuyensinh.ueh.edu.vn/bai-viet/thac-si-chuong-trinh-quan-tri-do-thi-thong-minh-va-sang-tao-huong-ung-dung/\" rel=\"noopener noreferrer nofollow\" target=\"_blank\"><span><u>LINK</u></span></a><span><u> </u></span></p>\r\n\r\n<p><span>Mọi thắc mắc vui l&ograve;ng li&ecirc;n hệ:</span></p>\r\n\r\n<p><span>📞 TS. Phạm Nguyễn Ho&agrave;i (0000 000 001)<br />\r\n📞 TS. Ho&agrave;ng Ngọc Lan (0000 000 002)</span></p>\r\n", "uid": 304, "cat_uid": 222, "category_name": "Tuyển sinh & Hướng nghiệp", "title": "Khám phá lộ trình học tập linh hoạt chỉ có ở chương trình Thạc sĩ Quản trị Đô thị Thông minh và Sáng tạo tại UEH-ISCM", "short_desc": "Trong bối cảnh đô thị hóa diễn ra mạnh mẽ và Cách mạng Công nghiệp 4.0 đang làm thay đổi phương thức sống, làm việc và quản lý đô thị, nhu cầu về nguồn nhân lực chất lượng cao trong lĩnh vực quản trị đô thị thông minh ngày càng trở nên cấp thiết. Đón đầu xu hướng đó, từ năm 2021, Đại học Kinh tế TP. Hồ Chí Minh (UEH) đã tiên phong triển khai Chương trình Thạc sĩ Quản trị Đô thị Thông minh và Sáng tạo (Master of Smart City and Innovation Management – MSCIM), do Viện Đô thị Thông minh và Quản lý (ISCM) quản lý.", "post_date": "2026-04-01T07:00:00", "sdgs": [4, 11], "is_featured": false, "background_img": "https://api.ngoisaoviet.infohttps://iscm-api.ueh.edu.vn/public/static/images/open-admission/kham-pha-lo-trinh-hoc-tap-linh-hoat-chi-co-o-chuong-trinh-thac-si-quan-tri-do-thi-thong-minh-va-sang-tao-tai-ueh-iscm/image1.png", "thumbnail_img": "https://api.ngoisaoviet.infohttps://iscm-api.ueh.edu.vn/public/static/images/open-admission/kham-pha-lo-trinh-hoc-tap-linh-hoat-chi-co-o-chuong-trinh-thac-si-quan-tri-do-thi-thong-minh-va-sang-tao-tai-ueh-iscm/image1.png"}''';
